<script setup>
import { computed,onMounted,ref } from "vue";
import { useRoute } from "vue-router";
import DashboardLayout from "../../layouts/DashboardLayout.vue";
import { getMemberProfile } from "../../services/member.service.js";
const route=useRoute();const profile=ref(null);const loading=ref(true);const errorMessage=ref("");const filter=ref("all");
const member=computed(()=>profile.value?.member||{});const summary=computed(()=>profile.value?.summary||{});const activities=computed(()=>filter.value==="all"?(profile.value?.activity||[]):(profile.value?.activity||[]).filter(x=>x.kind===filter.value));
const money=v=>new Intl.NumberFormat("en-TZ",{style:"currency",currency:"TZS",maximumFractionDigits:0}).format(Number(v)||0);const date=v=>v?new Date(v).toLocaleString():"—";const title=v=>String(v||"").replaceAll("_"," ");
const load=async()=>{loading.value=true;errorMessage.value="";try{profile.value=(await getMemberProfile(route.params.id)).data.data;}catch(error){errorMessage.value=error.response?.data?.message||"Unable to load member profile.";}finally{loading.value=false;}};onMounted(load);
const cards=computed(()=>[{label:"Total savings",value:money(summary.value.total_savings),icon:"bi-wallet2"},{label:"Shares / Hisa",value:`${summary.value.total_shares||0} · ${money(summary.value.total_share_value)}`,icon:"bi-stack"},{label:"Outstanding loans",value:money(summary.value.outstanding_loans),icon:"bi-bank"},{label:"Unpaid penalties",value:money(summary.value.unpaid_penalties),icon:"bi-exclamation-diamond"}]);
</script>
<template><DashboardLayout page-title="Member profile" page-subtitle="Members"><div v-if="loading" class="profile-state"><span class="spinner-border spinner-border-sm"></span>Loading member details...</div><div v-else-if="errorMessage" class="profile-state error"><i class="bi bi-exclamation-circle"></i>{{ errorMessage }}<button @click="load">Try again</button></div><div v-else class="member-profile"><router-link class="back-link" to="/members"><i class="bi bi-arrow-left"></i>Back to members</router-link><section class="identity"><span class="large-avatar">{{ member.first_name?.[0] }}{{ member.last_name?.[0] }}</span><div><small>MEMBER #{{ member.id }}</small><h2>{{ member.first_name }} {{ member.last_name }}</h2><p><span><i class="bi bi-phone"></i>{{ member.phone }}</span><span v-if="member.email"><i class="bi bi-envelope"></i>{{ member.email }}</span><span><i class="bi bi-calendar3"></i>Joined {{ new Date(member.created_at).toLocaleDateString() }}</span></p></div></section><section class="summary-grid"><article v-for="card in cards" :key="card.label"><i class="bi" :class="card.icon"></i><div><span>{{ card.label }}</span><strong>{{ card.value }}</strong></div></article></section><section class="profile-grid"><article class="activity-panel"><header><div><small>COMPLETE HISTORY</small><h3>Member activity</h3></div><select v-model="filter" class="form-select"><option value="all">All activity</option><option value="transaction">Transactions</option><option value="repayment">Repayments</option><option value="penalty">Penalties</option><option value="share">Shares</option><option value="social_fund">Social fund</option><option value="attendance">Attendance</option></select></header><div v-if="activities.length" class="timeline"><div v-for="item in activities" :key="item.id" class="event"><span class="event-icon" :class="item.kind"><i class="bi" :class="{transaction:'bi-arrow-left-right',repayment:'bi-arrow-repeat',penalty:'bi-exclamation-lg',share:'bi-stack',social_fund:'bi-heart-pulse',attendance:'bi-calendar-check'}[item.kind]"></i></span><div><strong>{{ item.title }}</strong><span>{{ title(item.meta) }}<template v-if="item.status"> · {{ title(item.status) }}</template></span><time>{{ date(item.occurred_at) }}</time></div><b v-if="Number(item.amount)">{{ item.direction==='outflow'?'−':'+' }} {{ money(item.amount) }}</b></div></div><div v-else class="empty">No activity found for this filter.</div></article><aside><section><h3>Loan accounts</h3><div v-for="loan in profile.loans" :key="loan.id" class="compact-row"><div><strong>Loan #{{ loan.id }}</strong><span>{{ title(loan.status) }}</span></div><b>{{ money(loan.remaining_balance) }}</b></div><p v-if="!profile.loans.length" class="empty">No loans.</p></section><section><h3>Meeting record</h3><div v-for="entry in profile.attendance.slice(0,5)" :key="entry.id" class="compact-row"><div><strong>{{ title(entry.attendance_status) }}</strong><span>{{ new Date(entry.meeting_date).toLocaleDateString() }}</span></div><b>{{ money(entry.contribution_amount) }}</b></div><p v-if="!profile.attendance.length" class="empty">No attendance records.</p></section></aside></section></div></DashboardLayout></template>
<style scoped>.member-profile{display:grid;gap:1rem}.back-link{width:max-content;color:#6d54d7;text-decoration:none;font-size:.72rem}.identity{display:flex;align-items:center;gap:1rem;padding:1.2rem;border:1px solid #e9e7ed;border-radius:14px;background:linear-gradient(135deg,#fff,#f8f6ff)}.large-avatar{width:4rem;height:4rem;display:grid;place-items:center;flex:none;border-radius:15px;background:#7357df;color:#fff;font-size:1.15rem;font-weight:800}.identity small,.activity-panel header small{color:#7659e8;font-size:.6rem;font-weight:800;letter-spacing:.08em}.identity h2{margin:.2rem 0;font-size:1.25rem}.identity p{display:flex;flex-wrap:wrap;gap:.65rem;margin:0;color:#7f7b85;font-size:.68rem}.identity p span{display:flex;gap:.3rem}.summary-grid{display:grid;grid-template-columns:1fr;gap:.65rem}.summary-grid article{display:flex;align-items:center;gap:.7rem;padding:1rem;border:1px solid #e9e7ed;border-radius:11px;background:#fff}.summary-grid article>i{width:2.1rem;height:2.1rem;display:grid;place-items:center;border-radius:8px;background:#eeeaff;color:#6d54d7}.summary-grid span,.summary-grid strong{display:block}.summary-grid span{color:#88848e;font-size:.63rem}.summary-grid strong{margin-top:.2rem;font-size:.82rem}.profile-grid{display:grid;gap:1rem}.activity-panel,.profile-grid aside section{border:1px solid #e9e7ed;border-radius:12px;background:#fff;overflow:hidden}.activity-panel header{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem;border-bottom:1px solid #eee}.activity-panel h3,.profile-grid aside h3{margin:.15rem 0 0;font-size:.9rem}.activity-panel select{width:140px;font-size:.68rem}.event{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:.7rem;padding:.8rem 1rem;border-bottom:1px solid #f0eef2}.event-icon{width:2rem;height:2rem;display:grid;place-items:center;border-radius:8px;background:#eeeaff;color:#6d54d7}.event-icon.penalty{background:#fff0f1;color:#c44a57}.event-icon.repayment,.event-icon.share{background:#eaf9f1;color:#168657}.event strong,.event span,.event time{display:block}.event strong{font-size:.72rem}.event span,.event time{color:#8a8690;font-size:.61rem}.event b{font-size:.68rem;white-space:nowrap}.profile-grid aside{display:grid;align-content:start;gap:1rem}.profile-grid aside section h3{padding:1rem;border-bottom:1px solid #eee}.compact-row{display:flex;justify-content:space-between;gap:1rem;padding:.7rem 1rem;border-bottom:1px solid #f0eef2;font-size:.68rem}.compact-row strong,.compact-row span{display:block}.compact-row span{color:#8a8690;font-size:.61rem;text-transform:capitalize}.empty,.profile-state{padding:2rem;text-align:center;color:#8a8690;font-size:.72rem}.profile-state{display:flex;align-items:center;justify-content:center;gap:.5rem;min-height:40vh}.profile-state button{border:0;border-radius:7px;background:#7659e8;color:#fff;padding:.5rem}.profile-state.error{color:#b3424e}@media(min-width:560px){.summary-grid{grid-template-columns:repeat(2,1fr)}}@media(min-width:960px){.summary-grid{grid-template-columns:repeat(4,1fr)}.profile-grid{grid-template-columns:minmax(0,1.7fr) minmax(260px,.7fr)}}@media(max-width:520px){.identity{align-items:flex-start}.identity p{display:grid}.activity-panel header{align-items:flex-start;flex-direction:column}.activity-panel select{width:100%}.event{grid-template-columns:auto 1fr}.event b{grid-column:2}}
</style>
